41	int GetOwningDevice(const nvcv::Byte *ptr)
42	{
43	    cudaPointerAttributes attrs = {};
44	    if (cudaError_t err = cudaPointerGetAttributes(&attrs, ptr);
45	        err == cudaSuccess && (attrs.type == cudaMemoryTypeDevice || attrs.type == cudaMemoryTypeManaged))
46	    {
47	        return attrs.device;
48	    }
49	    // cudaPointerGetAttributes leaves a sticky error on failure; clear it
50	    // so the subsequent cudaGetDevice call doesn't pick it up.
51	    cudaGetLastError();
52	    int dev = 0;
53	    util::CheckThrow(cudaGetDevice(&dev));
54	    return dev;
55	}
