96	    }
97	    dlTensor.ndim        = static_cast<int32_t>(info.ndim);
98	    dlTensor.device      = dev;
99	    dlTensor.byte_offset = 0;
100	
101	    m_tensor.deleter = DeleteShapeAndStrides;
102	
103	    try
104	    {
105	        auto shape = std::make_unique<int64_t[]>(info.ndim);
106	        std::copy_n(info.shape.begin(), info.shape.size(), shape.get());
107	        dlTensor.shape = shape.release();
108	
109	        auto strides = std::make_unique<int64_t[]>(info.ndim);
110	        for (int i = 0; i < info.ndim; ++i)
111	        {
112	            if (info.strides[i] % info.itemsize != 0)
113	            {
114	                throw DLPackError("Stride must be a multiple of the element size in bytes");
115	            }
116	
117	            strides[i] = info.strides[i] / info.itemsize;
118	        }
119	        dlTensor.strides = strides.release();
120	    }
121	    catch (...)
122	    {
123	        m_tensor.deleter(&m_tensor);
124	        throw;
125	    }
