293	nvcv::DataType ToNVCVDataType(const DLDataType &dtype)
294	{
295	    nvcv::PackingParams pp;
296	    pp.byteOrder = nvcv::ByteOrder::MSB;
297	
298	    int lanes = dtype.lanes;
299	    int bits  = dtype.bits;
300	
301	    switch (lanes)
302	    {
303	    case 1:
304	        pp.swizzle = nvcv::Swizzle::S_X000;
305	        break;
306	    case 2:
307	        pp.swizzle = nvcv::Swizzle::S_XY00;
308	        break;
309	    case 3:
310	        pp.swizzle = nvcv::Swizzle::S_XYZ0;
311	        break;
312	    case 4:
313	        pp.swizzle = nvcv::Swizzle::S_XYZW;
314	        break;
315	    default:
316	        throw DLPackError("DLPack buffer's data type must have at most 4 lanes");
317	    }
318	
319	    for (int i = 0; i < lanes; ++i)
320	    {
321	        pp.bits[i] = bits;
322	    }
323	    for (int i = lanes; i < 4; ++i)
324	    {
325	        pp.bits[i] = 0;
326	    }
327	
328	    nvcv::Packing packing = nvcv::MakePacking(pp);
329	
330	    nvcv::DataKind kind;
331	
332	    switch (dtype.code)
333	    {
334	    case kDLBool:
335	    case kDLInt:
336	        kind = nvcv::DataKind::SIGNED;
337	        break;
338	    case kDLUInt:
339	        kind = nvcv::DataKind::UNSIGNED;
340	        break;
341	    case kDLComplex:
342	        kind = nvcv::DataKind::COMPLEX;
343	        break;
344	    case kDLFloat:
345	        kind = nvcv::DataKind::FLOAT;
346	        break;
347	    default:
348	        throw DLPackError("Data type code not supported, must be Int, UInt, Float, Complex or Bool");
349	    }
350	
351	    return nvcv::DataType(kind, packing);
352	}
353	
354	DLDataType ToDLDataType(const nvcv::DataType &dataType)
355	{
356	    DLDataType dt = {};
357	    dt.lanes      = static_cast<uint16_t>(dataType.numChannels());
358	
359	    switch (dataType.dataKind())
360	    {
361	    case nvcv::DataKind::UNSIGNED:
362	        dt.code = kDLUInt;
363	        break;
364	    case nvcv::DataKind::SIGNED:
365	        dt.code = kDLInt;
366	        break;
367	    case nvcv::DataKind::FLOAT:
368	        dt.code = kDLFloat;
369	        break;
370	    case nvcv::DataKind::COMPLEX:
371	        dt.code = kDLComplex;
372	        break;
373	    default:
374	        throw DLPackError("Data kind not supported, must be UNSIGNED, SIGNED, FLOAT or COMPLEX");
375	    }
376	
377	    std::array<int32_t, 4> bpc = dataType.bitsPerChannel();
378	
379	    for (int i = 1; i < dataType.numChannels(); ++i)
380	    {
381	        if (bpc[i] != bpc[0])
382	        {
383	            throw DLPackError("All lanes must have the same bit depth");
384	        }
385	    }
386	
387	    dt.bits = static_cast<uint8_t>(bpc[0]);
388	
389	    return dt;
390	}
