85	std::shared_ptr<Tensor> Tensor::CreateFromReqs(const nvcv::Tensor::Requirements &reqs)
86	{
87	    std::vector<std::shared_ptr<CacheItem>> vcont = Cache::Instance().fetch(Key{reqs});
88	
89	    // None found?
90	    if (vcont.empty())
91	    {
92	        std::shared_ptr<Tensor> tensor(new Tensor(reqs)); // NOSONAR: constructor is private.
93	        Cache::Instance().add(*tensor);
94	        return tensor;
95	    }
96	    else
97	    {
98	        // Get the first one
99	        auto tensor = std::static_pointer_cast<Tensor>(vcont[0]);
100	        NVCV_ASSERT(tensor->dtype() == reqs.dtype);
101	        return tensor;
102	    }
103	}
