216	std::shared_ptr<Tensor> Tensor::ReshapeTensor(Tensor &tensor, Shape shape, std::optional<nvcv::TensorLayout> layout)
217	{
218	    Tensor::Key key;
219	    Cache::Instance().removeAllNotInUseMatching(key);
220	
221	    nvcv::Tensor tensor_impl      = tensor.impl();
222	    auto         new_tensor_shape = CreateNVCVTensorShape(shape, layout ? *layout : tensor_impl.layout());
223	    nvcv::Tensor new_tensor_impl  = tensor_impl.reshape(new_tensor_shape);
224	    auto         new_tensor
225	        = std::shared_ptr<Tensor>(new Tensor(std::move(new_tensor_impl))); // NOSONAR: constructor is private.
226	
227	    // Need to add wrappers to cache so that they don't get destroyed by
228	    // the cuda stream when they're last used, and python script isn't
229	    // holding a reference to them. If we don't do it, things might break.
230	    Cache::Instance().add(*new_tensor);
231	    return new_tensor;
232	}
