345	bool Tensor::Key::doIsCompatible(const IKey &that_) const
346	{
347	    const auto &that = static_cast<const Key &>(that_);
348	
349	    // Wrapper key's all compare equal, are they can't be used
350	    // and whenever we query the cache for wrappers, we really
351	    // want to get them all (as long as they aren't being used).
352	    if (m_wrapper && that.m_wrapper)
353	    {
354	        return true;
355	    }
356	    else if (m_wrapper || that.m_wrapper) // xor
357	    {
358	        return false;
359	    }
360	    else
361	    {
362	        return std::tie(m_shape, m_dtype) == std::tie(that.m_shape, that.m_dtype);
363	    }
364	}
