371	static py::object ToPython(const nvcv::TensorData &tensorData, py::object owner, cudaStream_t exportStream,
372	                           bool setExportStream)
373	{
374	    py::object out;
375	
376	    auto stridedData = tensorData.cast<nvcv::TensorDataStrided>();
377	    if (!stridedData)
378	    {
379	        throw TensorError("Only tensors with pitch-linear data can be exported");
380	    }
381	
382	    DLPackTensor dlTensor(*stridedData);
383	    return ExternalBuffer::Create(std::move(dlTensor), owner, exportStream, setExportStream);
384	}
385	
386	py::object Tensor::cuda() const
387	{
388	    nvcv::TensorData tensorData = m_impl.exportData();
389	
390	    // Advertise the stream the tensor's data was last written on via the
391	    // CAI `stream` field so downstream consumers (cupy/torch) can sync.
392	    // If the tensor has never been used by a cvcuda op, getLastStreamHandle()
393	    // returns 0 -- in which case we fall back to the default "stream: 1"
394	    // (legacy default) by not populating the export stream.
395	    cudaStream_t lastStream = this->getLastStreamHandle();
396	    bool         setStream  = lastStream != nullptr;
397	
398	    // Note: we can't cache the returned ExternalBuffer because it is holding
399	    // a reference to us. Doing so would lead to mem leaks.
400	    return ToPython(tensorData, py::cast(SharedContainerFrom(*this)), lastStream, setStream);
401	}
