53	static void CheckValidCUDABuffer(const std::byte *ptr)
54	{
55	    if (ptr == nullptr)
56	    {
57	        throw ExternalBufferError("NULL CUDA buffer not accepted");
58	    }
59	
60	    cudaPointerAttributes attrs = {};
61	    cudaError_t           err   = cudaPointerGetAttributes(&attrs, ptr);
62	    cudaGetLastError(); // reset the cuda error (if any)
63	    if (err != cudaSuccess || attrs.type == cudaMemoryTypeUnregistered)
64	    {
65	        throw ExternalBufferError("Buffer is not CUDA-accessible");
66	    }
67	}
