69	// Query the CUDA device a pointer lives on.  Returns -1 if the attributes
70	// can't be obtained (e.g. null pointer); callers then fall back to the
71	// current device.
72	static int GetCudaDeviceForPtr(const std::byte *ptr)
73	{
74	    if (ptr == nullptr)
75	    {
76	        return -1;
77	    }
78	
79	    cudaPointerAttributes attrs = {};
80	    cudaError_t           err   = cudaPointerGetAttributes(&attrs, ptr);
81	    cudaGetLastError();
82	    if (err != cudaSuccess)
83	    {
84	        return -1;
85	    }
86	    return attrs.device;
87	}
