89	// Parse the CAI `stream` field per the v3 spec:
90	//   absent / field missing : legacy default stream implied (producer was
91	//                            on stream 0)  --> handle = cudaStreamLegacy,
92	//                            isSynced = false
93	//   None / -1              : producer has synchronized; no wait needed
94	//                            --> handle = 0, isSynced = true
95	//   0                      : disallowed by spec but cupy emits this for
96	//                            its null stream; treat as legacy default
97	//                            --> handle = cudaStreamLegacy, isSynced = false
98	//   1                      : legacy default stream
99	//                            --> handle = cudaStreamLegacy
100	//   2                      : per-thread default stream
101	//                            --> handle = cudaStreamPerThread
102	//   other positive int     : raw stream handle
103	static void ParseCAIStreamField(const py::dict &iface, cudaStream_t &outHandle, bool &outIsSynced)
104	{
105	    outHandle   = reinterpret_cast<cudaStream_t>(1); // cudaStreamLegacy
106	    outIsSynced = false;
107	
108	    if (!iface.contains("stream"))
109	    {
110	        return; // legacy default
111	    }
112	
113	    py::object sf = iface["stream"];
114	    if (sf.is_none())
115	    {
116	        outHandle   = nullptr;
117	        outIsSynced = true;
118	        return;
119	    }
120	
121	    long value = 0;
122	    try
123	    {
124	        value = sf.cast<long>();
125	    }
126	    catch (py::cast_error &)
127	    {
128	        // Unparseable stream field; conservative default.
129	        return;
130	    }
131	
132	    if (value == -1)
133	    {
134	        outHandle   = nullptr;
135	        outIsSynced = true;
136	        return;
137	    }
138	    if (value == 0 || value == 1)
139	    {
140	        outHandle = reinterpret_cast<cudaStream_t>(1); // cudaStreamLegacy
141	        return;
142	    }
143	    if (value == 2)
144	    {
145	        outHandle = reinterpret_cast<cudaStream_t>(2); // cudaStreamPerThread
146	        return;
147	    }
148	    outHandle = reinterpret_cast<cudaStream_t>(value);
149	}
150	
151	// Parse the DLPack v1 `stream` kwarg to `__dlpack__`:
152	//   None / 0 / -1        : no synchronization requested; producer should
153	//                          not insert a cross-stream wait
154	//                          --> outConsumerStream = 0, outNeedSync = false
155	//   1                    : legacy default stream
156	//                          --> outConsumerStream = cudaStreamLegacy,
157	//                              outNeedSync = true
158	//   2                    : per-thread default stream
159	//                          --> outConsumerStream = cudaStreamPerThread,
160	//                              outNeedSync = true
161	//   other int            : consumer's CUDA stream handle
162	//                          --> outConsumerStream = handle, outNeedSync = true
163	//
164	// See https://dmlc.github.io/dlpack/latest/python_spec.html.  Note that
165	// None/0/-1 all map to "no sync" — the consumer is asserting they'll
166	// handle synchronization themselves (or the data is already retired).
167	static void ParseDLPackStreamArg(const py::object &streamArg, cudaStream_t &outConsumerStream, bool &outNeedSync)
168	{
169	    outConsumerStream = nullptr;
170	    outNeedSync       = false;
171	
172	    if (streamArg.is_none())
173	    {
174	        return; // no sync
175	    }
176	
177	    long value = 0;
178	    try
179	    {
180	        value = streamArg.cast<long>();
181	    }
182	    catch (py::cast_error &)
183	    {
184	        // Unparseable stream arg; conservative: no sync, consumer is on
185	        // their own.  This also covers edge cases like callers passing a
186	        // cupy.cuda.Stream object directly (which pybind11 may not cast).
187	        return;
188	    }
189	
190	    if (value == 0 || value == -1)
191	    {
192	        return; // no sync
193	    }
194	    if (value == 1)
195	    {
196	        outConsumerStream = reinterpret_cast<cudaStream_t>(1); // cudaStreamLegacy
197	        outNeedSync       = true;
198	        return;
199	    }
200	    if (value == 2)
201	    {
202	        outConsumerStream = reinterpret_cast<cudaStream_t>(2); // cudaStreamPerThread
203	        outNeedSync       = true;
204	        return;
205	    }
206	    outConsumerStream = reinterpret_cast<cudaStream_t>(value);
207	    outNeedSync       = true;
208	}
