210	// RAII guard that destroys a `cudaEvent_t` on scope exit.  Used below so
211	// an exception thrown from `cudaEventRecord` or `cudaStreamWaitEvent`
212	// cannot leak the event that was just created.  Declared local to this
213	// translation unit since no other file here needs it.
214	namespace {
215	struct ScopedCudaEvent
216	{
217	    cudaEvent_t handle = nullptr;
218	
219	    ScopedCudaEvent()                                   = default;
220	    ScopedCudaEvent(const ScopedCudaEvent &)            = delete;
221	    ScopedCudaEvent &operator=(const ScopedCudaEvent &) = delete;
222	    ScopedCudaEvent(ScopedCudaEvent &&)                 = delete;
223	    ScopedCudaEvent &operator=(ScopedCudaEvent &&)      = delete;
224	
225	    ~ScopedCudaEvent()
226	    {
227	        if (handle != nullptr)
228	        {
229	            util::CheckLog(cudaEventDestroy(handle));
230	        }
231	    }
232	};
