341	
342	// Insert a cross-stream synchronization into the consumer's stream before
343	// returning a DLPack capsule that exposes writer-stream-pending data.
344	//
345	// Records a fresh event on the producer's writer stream and queues a wait
346	// on the consumer's stream.  Per CUDA docs the event may be destroyed
347	// immediately after `cudaStreamWaitEvent` returns (the wait captures a
348	// snapshot of the recording), so we destroy it on scope exit via
349	// `ScopedCudaEvent`.
350	//
351	// Semantics:
352	//   * Writer stream unknown (buffer wasn't produced by cvcuda, i.e.
353	//     m_hasExportStream is false or handle is null) — nothing to sync,
354	//     return.
355	//   * Writer == consumer — sync is trivial (stream is sequential),
356	//     return.
357	//   * Writer == opted-out sentinel (nullptr) from `setExportStream(
358	//     (cudaStream_t)-1)` — producer has asserted no sync is needed,
359	//     return.
360	//   * Otherwise — insert `cudaEventRecord`+`cudaStreamWaitEvent`.
361	void InsertDLPackStreamSync(cudaStream_t writerStream, cudaStream_t consumerStream)
362	{
363	    if (writerStream == nullptr || writerStream == consumerStream)
364	    {
365	        return;
366	    }
367	
368	    ScopedCudaEvent evt;
369	    util::CheckThrow(cudaEventCreateWithFlags(&evt.handle, cudaEventDisableTiming));
370	    util::CheckThrow(cudaEventRecord(evt.handle, writerStream));
371	    util::CheckThrow(cudaStreamWaitEvent(consumerStream, evt.handle, 0));
372	    // evt destroyed by ScopedCudaEvent destructor on return / on any
373	    // exception propagating out of the CheckThrow calls above.
374	}
375	
376	std::string ToFormatString(const DLDataType &dtype)
377	{
378	    py::dtype dt = ToDType(ToNVCVDataType(dtype));
379	    return dt.attr("str").cast<std::string>();
