381	
382	std::unique_ptr<int64_t[]> ParseCAIShape(const py::tuple &shape)
383	{
384	    auto shapeData = std::make_unique<int64_t[]>(shape.size());
385	
386	    for (size_t i = 0; i < shape.size(); ++i)
387	    {
388	        shapeData[i] = shape[i].cast<long>();
389	    }
390	
391	    return shapeData;
392	}
393	
394	std::unique_ptr<int64_t[]> ParseCAIStrides(const py::dict &iface, int ndim, const int64_t *shape, int64_t itemSize)
395	{
396	    auto stridesData = std::make_unique<int64_t[]>(ndim);
397	
398	    if (iface.contains("strides") && !iface["strides"].is_none())
399	    {
400	        py::tuple strides = iface["strides"].cast<py::tuple>();
401	        for (int i = 0; i < ndim; ++i)
402	        {
403	            int64_t strideBytes = strides[i].cast<long>();
404	            if (strideBytes % itemSize != 0)
405	            {
406	                throw ExternalBufferError("Stride must be a multiple of the element size in bytes");
407	            }
408	            stridesData[i] = strideBytes / itemSize;
409	        }
410	        return stridesData;
411	    }
412	
413	    if (ndim <= 0)
414	    {
415	        return stridesData;
416	    }
417	
418	    // If strides isn't defined, according to cuda array interface, we must
419	    // set them up for packed, row-major strides.
420	    stridesData[ndim - 1] = 1;
421	    for (int i = ndim - 1; i > 0; --i)
422	    {
423	        stridesData[i - 1] = stridesData[i] * shape[i];
424	    }
425	    return stridesData;
426	}
427	
428	bool HasRequiredCAIFields(const py::dict &iface)
429	{
430	    return iface.contains("shape") && iface.contains("typestr") && iface.contains("data") && iface.contains("version");
431	}
432	
433	py::capsule RequestDLPackCapsule(const py::object &object)
434	{
435	    try
436	    {
437	        return object.attr("__dlpack__")("stream"_a = 1, "max_version"_a = py::make_tuple(1, 0)).cast<py::capsule>();
438	    }
439	    catch (py::error_already_set &)
440	    {
441	        // Producer doesn't accept max_version (v0 producer) -- retry without it.
442	        PyErr_Clear();
443	        return object.attr("__dlpack__")("stream"_a = 1).cast<py::capsule>();
444	    }
445	}
446	
447	} // namespace
448	
449	py::object ExternalBuffer::Create(DLPackTensor &&dlPackTensor, py::object wrappedObj, cudaStream_t exportStream,
450	                                  bool setExportStream)
451	{
452	    auto buf = std::make_shared<ExternalBuffer>(std::move(dlPackTensor));
453	
454	    if (setExportStream)
455	    {
456	        buf->setExportStream(exportStream);
457	    }
458	
459	    // We must make the returned object keep wrappedObj alive.
460	    // Using py::return_value_policy::reference_internal in py::cast doesn't work
461	    // because buf is a shared_ptr.
462	    py::object o = py::cast(buf);
463	    py::detail::keep_alive_impl(o, wrappedObj);
464	
465	    // If we expose cuda array interface,
466	    if (auto iface = buf->cudaArrayInterface())
467	    {
468	        o.attr("__cuda_array_interface__") = *iface;
469	    }
470	
471	    return o;
472	}
473	
474	ExternalBuffer::ExternalBuffer(DLPackTensor &&dlTensor)
475	{
476	    if (!IsCudaAccessible(dlTensor->device.device_type))
477	    {
478	        throw ExternalBufferError("Only CUDA memory buffers can be wrapped");
479	    }
480	
481	    if (dlTensor->data != nullptr)
482	    {
483	        CheckValidCUDABuffer(static_cast<const std::byte *>(dlTensor->data));
484	    }
485	
486	    m_dlTensor = std::move(dlTensor);
487	}
488	
489	Shape ExternalBuffer::shape() const
490	{
491	    Shape shape(m_dlTensor->ndim);
492	    for (size_t i = 0; i < shape.size(); ++i)
493	    {
494	        shape[i] = m_dlTensor->shape[i];
495	    }
496	
497	    return shape;
498	}
499	
500	py::tuple ExternalBuffer::strides() const
501	{
502	    py::tuple strides(m_dlTensor->ndim);
503	
504	    for (size_t i = 0; i < strides.size(); ++i)
505	    {
506	        strides[i] = m_dlTensor->strides[i];
507	    }
508	
509	    return strides;
510	}
511	
512	py::object ExternalBuffer::dtype() const
513	{
514	    return ToDType(ToNVCVDataType(m_dlTensor->dtype));
515	}
516	
517	bool ExternalBuffer::load(PyObject *o)
518	{
519	    if (!o)
520	    {
521	        return false;
522	    }
523	
524	    py::object tmp = py::reinterpret_borrow<py::object>(o);
525	    if (hasattr(tmp, "__cuda_array_interface__"))
526	    {
527	        return loadCudaArrayInterface(tmp);
528	    }
529	
530	    if (hasattr(tmp, "__dlpack__"))
531	    {
532	        return loadDLPack(tmp);
533	    }
534	
535	    return false;
536	}
537	
538	bool ExternalBuffer::loadCudaArrayInterface(const py::object &object)
539	{
540	    py::dict iface = object.attr("__cuda_array_interface__").cast<py::dict>();
541	
542	    if (!HasRequiredCAIFields(iface))
543	    {
544	        return false;
545	    }
546	
547	    if (int version = iface["version"].cast<int>(); version < 2)
548	    {
549	        return false;
550	    }
551	
552	    DLPackTensor dlTensor = CreateCAITensor();
553	    dlTensor->byte_offset = 0;
554	
555	    // REVISIT: infer the device type from the memory buffer
556	    dlTensor->device.device_type = kDLCUDA;
557	    // REVISIT: infer the device from the memory buffer
558	    dlTensor->device.device_id = 0;
559	
560	    py::tuple tdata = iface["data"].cast<py::tuple>();
561	    auto     *ptr   = AsBytePointer(tdata[0].cast<std::uintptr_t>());
562	    CheckValidCUDABuffer(ptr);
563	    dlTensor->data = ptr;
564	
565	    py::dtype dt = util::ToDType(iface["typestr"].cast<std::string>());
566	    if (std::optional<nvcv::DataType> dtype = ToNVCVDataType(dt))
567	    {
568	        dlTensor->dtype = ToDLDataType(*dtype);
569	    }
570	
571	    py::tuple shape = iface["shape"].cast<py::tuple>();
572	    dlTensor->ndim  = static_cast<int32_t>(shape.size());
573	    if (dlTensor->ndim < 1)
574	    {
575	        return false;
576	    }
577	
578	    auto shapeData    = ParseCAIShape(shape);
579	    auto stridesData  = ParseCAIStrides(iface, dlTensor->ndim, shapeData.get(), dt.itemsize());
580	    dlTensor->shape   = shapeData.release();
581	    dlTensor->strides = stridesData.release();
582	
583	    // Parse CAI v3 `stream` to record producer-stream info so the first cvcuda
584	    // op that reads this buffer can insert the appropriate cross-stream wait.
585	    ParseCAIStreamField(iface, m_producerStream, m_producerIsSynced);
586	    m_producerDevice = GetCudaDeviceForPtr(static_cast<const std::byte *>(dlTensor->data));
587	    if (m_producerDevice >= 0)
588	    {
589	        dlTensor->device.device_id = m_producerDevice;
590	    }
591	
592	    m_wrappedObj              = object;
593	    m_cacheCudaArrayInterface = std::move(iface);
594	    m_dlTensor                = std::move(dlTensor);
595	    return true;
596	}
597	
598	bool ExternalBuffer::loadDLPack(const py::object &object)
599	{
600	    if (hasattr(object, "__dlpack_device__"))
601	    {
602	        py::tuple dlpackDevice = object.attr("__dlpack_device__")().cast<py::tuple>();
603	        auto      devType      = static_cast<DLDeviceType>(dlpackDevice[0].cast<int>());
604	        if (!IsCudaAccessible(devType))
605	        {
606	            throw ExternalBufferError("Only CUDA-accessible memory buffers can be wrapped");
607	        }
608	    }
609	
610	    py::capsule cap = RequestDLPackCapsule(object);
611	    loadDLPackCapsule(cap);
612	
613	    // DLPack does not thread a producer-stream field through the capsule the
614	    // way CAI does. We asked for stream=1, so seed that as the producer stream
615	    // for the first cvcuda op that consumes the buffer.
616	    if (m_dlTensor->data != nullptr)
617	    {
618	        m_producerStream   = reinterpret_cast<cudaStream_t>(1);
619	        m_producerIsSynced = false;
620	        m_producerDevice   = GetCudaDeviceForPtr(static_cast<const std::byte *>(m_dlTensor->data));
621	    }
622	
623	    return true;
624	}
625	
626	void ExternalBuffer::loadDLPackCapsule(py::capsule &cap)
627	{
628	    if (PyCapsule_IsValid(cap.ptr(), "dltensor_versioned"))
629	    {
630	        auto *vt = static_cast<DLManagedTensorVersioned *>(PyCapsule_GetPointer(cap.ptr(), "dltensor_versioned"));
631	        if (vt != nullptr)
632	        {
633	            m_dlTensor = DLPackTensor{vt->dl_tensor};
634	            m_dlManagedVersioned.reset(vt);
635	            PyCapsule_SetName(cap.ptr(), "used_dltensor_versioned");
636	            return;
637	        }
638	    }
639	    else if (PyCapsule_IsValid(cap.ptr(), "dltensor"))
640	    {
641	        if (auto *tensor = static_cast<DLManagedTensor *>(PyCapsule_GetPointer(cap.ptr(), "dltensor")))
642	        {
643	            m_dlTensor = DLPackTensor{std::move(*tensor)};
644	            PyCapsule_SetName(cap.ptr(), "used_dltensor");
645	            return;
646	        }
647	    }
648	
649	    m_dlTensor = {};
650	}
651	
652	std::optional<py::dict> ExternalBuffer::cudaArrayInterface() const
653	{
654	    if (!m_cacheCudaArrayInterface)
655	    {
656	        if (!IsCudaAccessible(m_dlTensor->device.device_type))
657	        {
658	            return std::nullopt;
659	        }
660	
661	        nvcv::DataType dataType = ToNVCVDataType(m_dlTensor->dtype);
662	
663	        NVCV_ASSERT(m_dlTensor->dtype.bits % 8 == 0);
664	        NVCV_ASSERT(dataType.strideBytes() * 8 == m_dlTensor->dtype.bits * m_dlTensor->dtype.lanes);
665	        int elemStrideBytes = dataType.strideBytes();
666	
667	        py::object strides;
668	
669	        if (m_dlTensor->strides == nullptr)
670	        {
671	            strides = py::none();
672	        }
673	        else
674	        {
675	            py::tuple vStrides(m_dlTensor->ndim);
676	            for (size_t i = 0; i < vStrides.size(); ++i)
677	            {
678	                vStrides[i] = m_dlTensor->strides[i] * elemStrideBytes;
679	            }
680	            strides = vStrides;
681	        }
682	
683	        std::string format = ToFormatString(m_dlTensor->dtype);
684	
685	        // CAI v3 `stream` field — advertise which stream the consumer must
686	        // synchronize with before reading.  If an export stream was set
687	        // (typically by Tensor::cuda() from the owning tensor's last-writer
688	        // stream), emit its integer handle.  Otherwise, default to `1` (legacy
689	        // default stream), which is the safe conservative value per the CAI
690	        // spec and matches behavior for locally-constructed buffers whose
691	        // writer stream is unknown.
692	        long streamValue = 1; // cudaStreamLegacy
693	        if (m_hasExportStream)
694	        {
695	            // m_exportStream == nullptr means "no sync needed" (-1 per spec),
696	            // typically used when the producer has already synchronized.
697	            streamValue = m_exportStream == nullptr ? -1L : reinterpret_cast<intptr_t>(m_exportStream);
698	        }
699	
700	        // clang-format off
701	        m_cacheCudaArrayInterface = py::dict
702	        {
703	            "shape"_a = this->shape(),
704	            "strides"_a = strides,
705	            "typestr"_a = format,
706	            "data"_a = py::make_tuple(reinterpret_cast<long>(m_dlTensor->data), false /* read/write */),
707	            "stream"_a = streamValue,
708	            "version"_a = 3
709	        };
710	    }
711	
712	    return *m_cacheCudaArrayInterface;
713	}
714	
715	py::capsule ExternalBuffer::dlpack(py::object stream, py::object maxVersion) const
716	{
717	    // Honor the DLPack v1 `stream` contract: when the consumer passes a
718	    // CUDA stream, synchronize the writer stream into it before returning
719	    // the capsule so any work the consumer queues on that stream waits for
720	    // our pending writes.  `m_hasExportStream` is set by Tensor::cuda() /
721	    // Image::cuda() / Array::cuda() when a cvcuda op last wrote the buffer;
722	    // if it's unset the buffer wasn't produced by cvcuda (pass-through
723	    // import), and we have no writer stream to sync.
724	    if (m_hasExportStream)
725	    {
726	        cudaStream_t consumerStream = nullptr;
727	        bool         needSync       = false;
728	        ParseDLPackStreamArg(stream, consumerStream, needSync);
729	        if (needSync)
730	        {
731	            // m_exportStream == -1 sentinel means the producer asserted
732	            // the data is already synchronized (CAI v3 `stream: -1`
733	            // semantics); honor that by skipping the wait here too.
734	            cudaStream_t writerStream = m_exportStream;
735	            if (writerStream == reinterpret_cast<cudaStream_t>(-1))
736	            {
737	                writerStream = nullptr;
738	            }
739	            InsertDLPackStreamSync(writerStream, consumerStream);
740	        }
741	    }
742	
743	    if (UseVersionedDLPack(maxVersion))
744	    {
745	        return CreateVersionedDLPackCapsule(*m_dlTensor, this->shared_from_this());
746	    }
747	
748	    return CreateLegacyDLPackCapsule(*m_dlTensor, this->shared_from_this());
749	}
750	
751	py::tuple ExternalBuffer::dlpackDevice() const
752	{
753	    return py::make_tuple(py::int_(static_cast<int>(m_dlTensor->device.device_type)),
754	                          py::int_(m_dlTensor->device.device_id));
755	}
756	
757	const DLTensor &ExternalBuffer::dlTensor() const
758	{
759	    return *m_dlTensor;
760	}
761	
762	void ExternalBuffer::Export(py::module &m)
763	{
764	    py::class_<ExternalBuffer, std::shared_ptr<ExternalBuffer>>(m, "ExternalBuffer", py::dynamic_attr())
765	        .def_property_readonly("shape", &ExternalBuffer::shape, "Get the shape of the buffer as an array")
766	        .def_property_readonly("strides", &ExternalBuffer::strides, "Get the strides of the buffer")
767	        .def_property_readonly("dtype", &ExternalBuffer::dtype, "Get the data type of the buffer")
768	        .def("__dlpack__", &ExternalBuffer::dlpack, "stream"_a=1, "max_version"_a=py::none(),
769	             "Export the buffer as a DLPack tensor")
770	        .def("__dlpack_device__", &ExternalBuffer::dlpackDevice, "Get the device associated with the buffer");
771	}
772	
773	} // namespace nvcvpy::priv
774	
775	namespace pybind11::detail {
776	
777	namespace priv = nvcvpy::priv;
778	
779	// Python -> C++
780	bool type_caster<priv::ExternalBuffer>::load(handle src, bool)
781	{
782	    const PyTypeObject *srctype = Py_TYPE(src.ptr());
783	    const type_info *cuda_buffer_type = get_type_info(typeid(priv::ExternalBuffer));
784	
785	    // src's type is ExternalBuffer?
786	    if(srctype == cuda_buffer_type->type)
787	    {
788	        // We know it's managed by a shared pointer (holder), let's use it
789	        value_and_holder vh = reinterpret_cast<instance *>(src.ptr())->get_value_and_holder();
790	        value = vh.template holder<std::shared_ptr<priv::ExternalBuffer>>();
791	        NVCV_ASSERT(value != nullptr);
792	        return true;
793	    }
794	    // If not, it could be an object that implements that __cuda_array_interface, let's try to
795	    // create a ExternalBuffer out of it.
796	    else
797	    {
798	        value = std::make_shared<priv::ExternalBuffer>();
799	        return value->load(src.ptr());
800	    }
801	}
802	
803	} // namespace pybind11::detail
